    $router->post('/admin/portal/materials',static function(Request$request)use($organizationMaterials,$materialFiles,$organizationId,$auth,$session,$basePath):Response{try{$file=$materialFiles->storeUploaded($request->file('file'));if($file===null)throw new RuntimeException('Selecione um arquivo (PDF, imagem, Word ou áudio).');$organizationMaterials->create($organizationId,(string)$request->input('title',''),$file,$auth->user()?->id);$session->flash('announcements.message','Material publicado no Portal do Aluno.');}catch(Throwable$e){$session->flash('announcements.error',$e->getMessage());}return Response::redirect($basePath.'/admin/portal/materials');},[$requireAuth,new RequirePermission($auth,'users.manage')]);
    $router->post('/admin/portal/materials/{id:\d+}/delete',static function(Request$request,array$params)use($organizationMaterials,$organizationId,$session,$basePath):Response{try{$organizationMaterials->delete((int)$params['id'],$organizationId);$session->flash('announcements.message','Material removido.');}catch(Throwable$e){$session->flash('announcements.error',$e->getMessage());}return Response::redirect($basePath.'/admin/portal/materials');},[$requireAuth,new RequirePermission($auth,'users.manage')]);
    $router->get('/admin/portal/satisfaction',static function(Request$request)use($view,$organizationSatisfaction,$organizationId,$session,$basePath,$browserTitle):Response{return$view->render('admin/portal-satisfaction',['title'=>'Satisfação — '.$browserTitle,'summary'=>$organizationSatisfaction->summary($organizationId),'responses'=>$organizationSatisfaction->recent($organizationId),'basePath'=>$basePath]);},[$requireAuth,new RequirePermission($auth,'users.manage')]);

    $documentResponse=static function(Request$request,array$document)use($documents):Response{
        try{$body=$documents->read($document);$mime=(string)$document['mime_type'];$inline=$request->queryValue('inline')==='1'&&($mime==='application/pdf'||str_starts_with($mime,'image/'));$name=preg_replace('/[^\pL\pN._ -]+/u','_',basename((string)$document['original_name']))?:'documento';return(new Response($body,200))->withHeaders(['Content-Type'=>$mime,'Content-Length'=>(string)strlen($body),'Content-Disposition'=>($inline?'inline':'attachment').'; filename="'.str_replace('"','',$name).'"','X-Content-Type-Options'=>'nosniff','Cache-Control'=>'private, no-store','Content-Security-Policy'=>"default-src 'none'; sandbox"]);}catch(Throwable){return Response::text("Documento indisponível.\n",404);}
    };
    $router->post('/admin/organizations/{id:\d+}/documents',static function(Request$request,array$params)use($organizations,$documents,$platformAdmin,$auth,$session,$basePath):Response{if(!$platformAdmin())return Response::text("Acesso restrito ao ADM Central.\n",403);$id=(int)$params['id'];try{if($organizations->findRecord($id)===null)throw new RuntimeException('Franquia não encontrada.');$file=$request->file('document');if($file===null)throw new RuntimeException('Selecione um arquivo.');$documents->upload('franchise',$id,$file,(string)$request->input('title',''),(string)$request->input('category',''),(string)$request->input('description',''),((int)$request->input('replace_id','0'))?:null,$auth->user()->id);$session->flash('documents.message','Documento da franquia armazenado com segurança.');}catch(Throwable$e){$session->flash('documents.error',$e->getMessage());}return Response::redirect($basePath.'/admin/organizations/'.$id.'/edit#documentos');},[$requireAuth,new RequirePermission($auth,'users.manage')]);
    $router->get('/admin/organizations/{id:\d+}/documents/{document:\d+}/download',static function(Request$request,array$params)use($documents,$documentResponse,$platformAdmin):Response{if(!$platformAdmin())return Response::text("Acesso restrito ao ADM Central.\n",403);$document=$documents->find((int)$params['document'],'franchise',(int)$params['id']);return$document===null?Response::text("Documento não encontrado.\n",404):$documentResponse($request,$document);},[$requireAuth,new RequirePermission($auth,'users.manage')]);
    $router->post('/admin/organizations/{id:\d+}/documents/{document:\d+}/delete',static function(Request$request,array$params)use($documents,$platformAdmin,$auth,$session,$basePath):Response{if(!$platformAdmin())return Response::text("Acesso restrito ao ADM Central.\n",403);$id=(int)$params['id'];try{$documents->archive((int)$params['document'],'franchise',$id,$auth->user()->id);$session->flash('documents.message','Documento arquivado. O histórico externo foi preservado.');}catch(Throwable$e){$session->flash('documents.error',$e->getMessage());}return Response::redirect($basePath.'/admin/organizations/'.$id.'/edit#documentos');},[$requireAuth,new RequirePermission($auth,'users.manage')]);

    $router->get('/cadastro-franquia',static function()use($view,$session,$csrf,$browserTitle,$basePath):Response{return$view->render('public/franchise-application',['currentUser'=>null,'wideGuest'=>true,'title'=>'Cadastro de franquia — '.$browserTitle,'application'=>[],'formAction'=>$basePath.'/cadastro-franquia','error'=>$session->get('franchise_public.error'),'csrfField'=>$csrf->field()]);});
    $router->post('/cadastro-franquia',static function(Request$request)use($franchiseApplications,$session,$basePath):Response{try{$franchiseApplications->submitNew(['display_name'=>$request->input('display_name',''),'legal_name'=>$request->input('legal_name',''),'cnpj'=>$request->input('cnpj',''),'state_registration'=>$request->input('state_registration',''),'municipal_registration'=>$request->input('municipal_registration',''),'postal_code'=>$request->input('postal_code',''),'address'=>$request->input('address',''),'address_number'=>$request->input('address_number',''),'address_complement'=>$request->input('address_complement',''),'neighborhood'=>$request->input('neighborhood',''),'city'=>$request->input('city',''),'state'=>$request->input('state',''),'manager_name'=>$request->input('manager_name',''),'manager_document'=>$request->input('manager_document',''),'manager_email'=>$request->input('manager_email',''),'manager_phone'=>$request->input('manager_phone',''),'general_manager_name'=>$request->input('general_manager_name',''),'general_manager_email'=>$request->input('general_manager_email',''),'general_manager_phone'=>$request->input('general_manager_phone',''),'site_host'=>$request->input('site_host',''),'negotiation_notes'=>$request->input('negotiation_notes','')]);return Response::redirect($basePath.'/cadastro-franquia/enviado');}catch(Throwable$e){$session->flash('franchise_public.error',$e->getMessage());return Response::redirect($basePath.'/cadastro-franquia');}});
