    $siteContext=static function()use($organizationId):void{if($organizationId<1)throw new RuntimeException('Franquia não encontrada.');};
    $siteAttribution=static fn(Request$request):array=>['landing_page'=>mb_substr((string)$request->input('landing_page',''),0,500)?:null,'utm_source'=>mb_substr((string)$request->input('utm_source',''),0,190)?:null,'utm_medium'=>mb_substr((string)$request->input('utm_medium',''),0,190)?:null,'utm_campaign'=>mb_substr((string)$request->input('utm_campaign',''),0,190)?:null,'utm_content'=>mb_substr((string)$request->input('utm_content',''),0,190)?:null,'utm_term'=>mb_substr((string)$request->input('utm_term',''),0,190)?:null];
    $siteSessionHash=static function(Request$request)use($organizationId):string{$sessionId=mb_substr(trim((string)$request->input('site_session_id','')),0,120);if($sessionId!=='')return hash('sha256',$organizationId.'|site-session|'.$sessionId);$ip=(string)$request->header('cf-connecting-ip',$request->header('x-forwarded-for','unknown'));$agent=(string)$request->header('user-agent','');return hash('sha256',$organizationId.'|fallback|'.$ip.'|'.$agent);};
    $trackSiteConversion=static function(Request$request,string$event,int$contactId,int$unitId,?int$orderId=null,?int$entityId=null)use($sites,$organizationId,$siteAttribution,$siteSessionHash):void{$attribution=$siteAttribution($request);$sites->recordEvent($organizationId,$attribution+['event_type'=>$event,'page_path'=>mb_substr((string)$request->input('landing_page',''),0,500),'entity_type'=>$orderId!==null?'order':'contact','entity_id'=>$entityId??($orderId??$contactId),'contact_id'=>$contactId,'order_id'=>$orderId,'unit_id'=>$unitId,'session_hash'=>$siteSessionHash($request)]);};
    $siteImage=static function(Request$request,string$field)use($spacesStorage,$organizationId,$auth):?array{
        $file=$request->file($field);if($file===null||$file->isEmpty())return null;
        if($file->error!==UPLOAD_ERR_OK||$file->temporaryPath===''||!is_uploaded_file($file->temporaryPath))throw new RuntimeException('Não foi possível receber a imagem do banner.');
        if($file->size<1||$file->size>8*1024*1024)throw new RuntimeException('A imagem deve possuir no máximo 8 MB.');
        $mime=(new finfo(FILEINFO_MIME_TYPE))->file($file->temporaryPath);$allowed=['image/jpeg'=>'jpg','image/png'=>'png','image/webp'=>'webp'];
        if(!is_string($mime)||!isset($allowed[$mime]))throw new RuntimeException('Envie o banner em JPG, PNG ou WEBP.');
        $content=file_get_contents($file->temporaryPath);if(!is_string($content)||$content==='')throw new RuntimeException('A imagem enviada está vazia.');
        $safe=(preg_replace('/[^A-Za-z0-9._-]+/','-',pathinfo($file->originalName,PATHINFO_FILENAME))?:'banner').'.'.$allowed[$mime];
        $path=$spacesStorage->storeFranchise($organizationId,'Site/Banners',$content,$safe,$mime,$auth->user()?->id);
        if($path===null)throw new RuntimeException('Ative a integração DigitalOcean Spaces antes de enviar banners.');
        return['path'=>$path,'mime'=>$mime,'name'=>$safe];
    };

    $router->get('/site',static function(Request$request)use($view,$config,$auth,$sites,$organizationId,$session,$csrf,$basePath):Response{
        $host=OrganizationRepository::normalizeHost((string)$request->header('host',''));
        $isCentralRoot=$host===OrganizationRepository::normalizeHost($config->string('app.central_host'))&&$basePath===$config->path('app.base_path');
        if($isCentralRoot||$organizationId<1)return$view->renderStandalone('site/unavailable',[],404);
        $preview=$request->queryValue('preview')==='1'&&$auth->check()&&$auth->can('users.manage');
        $site=$sites->publicSite($organizationId,$preview);
        if($site===null)return$view->renderStandalone('site/unavailable',[],503);
