    $router->post('/admin/platform/integrations/course-providers/courses/{id:\d+}/prepare-master-pilot',static function(Request$request,array$params)use($courseProviders,$catalogImages,$catalogCoverGenerator,$platformAdmin):Response{
        if(!$platformAdmin())return Response::json(['ok'=>false,'error'=>'Acesso restrito ao ADM Central.'],403);
        $id=(int)$params['id'];
        try{
            $context=$courseProviders->coursePublicationContext($id);
            if($context===null||(string)($context['provider_code']??'')!=='iesde')throw new RuntimeException('Este assistente é exclusivo da Formação MASTER.');
            $modules=[];
            foreach($courseProviders->courseResourcesForCourse($id)as$resource){
                $type=(string)($resource['content_type']??'');
