            $material=$organizationMaterials->find((int)$params['id'],(int)$customer['organization_id']);
            if($material===null||(int)$material['is_active']!==1)return Response::text("Material não encontrado.\n",404);
            $body=$materialFiles->read((string)$material['storage_path']);
            $name=preg_replace('/[^\pL\pN._ -]+/u','_',basename((string)$material['file_name']))?:'material';
            return(new Response($body,200))->withHeaders(['Content-Type'=>(string)$material['mime_type'],'Content-Length'=>(string)strlen($body),'Content-Disposition'=>'attachment; filename="'.str_replace('"','',$name).'"','X-Content-Type-Options'=>'nosniff','Cache-Control'=>'private, no-store','Content-Security-Policy'=>"default-src 'none'; sandbox"]);
        }catch(Throwable){return Response::text("Material indisponível.\n",404);}
    });

    $router->postWithoutCsrf('/portal/aluno/document',static function(Request$request)use($portalCustomer,$documents,$organizations):Response{
        try{
            $customer=$portalCustomer($request);
            $master=$organizations->panelUser((int)$customer['organization_id']);
            if($master===null)throw new RuntimeException('A franquia ainda não possui um operador responsável.');
            $file=$request->file('document');
            if($file===null)throw new RuntimeException('Selecione um arquivo.');
            $category=trim((string)$request->input('category',''));
            $categories=$documents->categories('franchise');
            if(!isset($categories[$category]))throw new RuntimeException('Selecione um tipo de documento válido.');
            $title=trim((string)$request->input('title',''));
            if($title==='')$title=(string)$file->originalName;
            $id=$documents->upload('franchise',(int)$customer['organization_id'],$file,$title,$category,trim((string)$request->input('description','')),null,(int)$master['id'],'student',(int)$customer['id']);
            return Response::json(['ok'=>true,'id'=>$id]);
        }catch(Throwable$e){return Response::json(['ok'=>false,'error'=>$e->getMessage()],422);}
    });

    $router->get('/health',static function()use($platformSettings):Response{
        $database=true;$status='ok';$http=200;
        try{$platformSettings->settings();}catch(Throwable){$database=false;$status='degraded';$http=503;}
        return(new Response(json_encode(['status'=>$status,'database'=>$database,'time'=>date('c')],JSON_UNESCAPED_UNICODE),$http))->withHeaders(['Content-Type'=>'application/json; charset=UTF-8','Cache-Control'=>'no-store']);
    });

    $router->get('/{path:.*}',static function(Request$request)use($database):Response{
        $path=(string)$request->path();
        $skip=preg_match('#\.(?:css|js|png|jpe?g|gif|svg|webp|ico|woff2?|ttf|map|txt|xml|json)(?:\?|$)#i',$path)===1||str_starts_with($path,'/wp-')||str_starts_with($path,'/favicon');
        if(!$skip){
            try{$statement=$database->prepare('INSERT INTO site_404_logs(host,path,referer,ip,user_agent) VALUES(:host,:path,:referer,:ip,:agent)');$statement->execute(['host'=>mb_substr((string)$request->header('host',''),0,190),'path'=>mb_substr($path,0,500),'referer'=>mb_substr((string)$request->header('referer',''),0,500),'ip'=>mb_substr((string)$request->header('cf-connecting-ip',$request->header('x-forwarded-for','')),0,64),'agent'=>mb_substr((string)$request->header('user-agent',''),0,255)]);}catch(Throwable){}
        }
        return Response::text("Página não encontrada.\n",404);
    });
};
